import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import org.commonmark.node.FencedCodeBlock;
import org.commonmark.node.Node;
import org.commonmark.parser.Parser;
import org.commonmark.renderer.html.HtmlRenderer;

/** Tests parser behavior over cumulative local prefixes, not provider/IDE streaming. */
public final class StreamingMarkdownProbe {
    public static void main(String[] args) throws Exception {
        List<String> deltas = List.of("## 演示\n\n```ja", "va\nint count", " = 1;\n", "```\n", "\n结束。");
        List<String> infos = List.of("ja", "java", "java", "java", "java");
        List<String> bodies = List.of("", "int count\n", "int count = 1;\n", "int count = 1;\n", "int count = 1;\n");
        Parser parser = Parser.builder().build();
        HtmlRenderer renderer = HtmlRenderer.builder().escapeHtml(true).build();
        StringBuilder raw = new StringBuilder();
        StringBuilder report = new StringBuilder("{\"status\":\"success\",\"cumulativePrefixes\":5,\"snapshots\":[");
        for (int i = 0; i < deltas.size(); i++) {
            raw.append(deltas.get(i));
            String snapshot = raw.toString();
            FencedCodeBlock fence = find(parser.parse(snapshot));
            if (fence == null || !fence.getInfo().equals(infos.get(i)) || !fence.getLiteral().equals(bodies.get(i))) {
                throw new IllegalStateException("Unexpected partial-fence behavior at snapshot " + i);
            }
            String html = renderer.render(parser.parse(snapshot));
            if (!raw.toString().equals(snapshot)) throw new IllegalStateException("Raw source changed");
            if (i > 0) report.append(',');
            report.append("{\"revision\":").append(i+1).append(",\"languageInfo\":\"")
                  .append(fence.getInfo()).append("\",\"rawLength\":").append(snapshot.length())
                  .append(",\"codeLiteralLength\":").append(fence.getLiteral().length())
                  .append(",\"htmlLength\":").append(html.length()).append('}');
        }
        report.append("],\"localParserOnly\":true,\"networkOrIntellijExecuted\":false,\"rawSourceMutated\":false}");
        Files.writeString(Path.of(args[0], "stream-prefix-result.json"), report, StandardCharsets.UTF_8);
        System.out.println(report);
    }
    private static FencedCodeBlock find(Node node) {
        if (node instanceof FencedCodeBlock fence) return fence;
        for (Node child = node.getFirstChild(); child != null; child = child.getNext()) {
            FencedCodeBlock found = find(child);
            if (found != null) return found;
        }
        return null;
    }
}
